using System;using System.Linq;using System.Collections.Generic;using System.IO;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;
namespace GlassBoard { internal static class SnapStyles{[System.Runtime.InteropServices.DllImport("user32.dll")]static extern int GetWindowLong(IntPtr h,int n);[System.Runtime.InteropServices.DllImport("user32.dll")]static extern int SetWindowLong(IntPtr h,int n,int v);internal static void MakePassive(IntPtr h){SetWindowLong(h,-20,GetWindowLong(h,-20)|0x20|0x08000000|0x80);}}
public static partial class RunningWindows {
internal static bool IsFileManager(Entry entry){
if(entry==null||entry.IsFolder)return false;
if(!string.IsNullOrEmpty(entry.LaunchArguments))return false;
var target=(entry.LaunchTarget??"").Trim();
if(target.Equals("文件资源管理器",StringComparison.OrdinalIgnoreCase))return true;
if(string.Equals(Path.GetFileName(target),"explorer.exe",StringComparison.OrdinalIgnoreCase))return true;
return string.Equals(Path.GetFileName(entry.Path??""),"File Explorer.lnk",StringComparison.OrdinalIgnoreCase);
}
static List<RunningWindow> MatchWindows(Entry entry,IEnumerable<string> paths){
if(IsFileManager(entry)){var folders=windows.Where(w=>!string.IsNullOrWhiteSpace(w.FolderPath)).ToList();if(folders.Count>0)return folders;}
var candidates=paths.Where(p=>!string.IsNullOrWhiteSpace(p)).ToArray();
var exact=windows.Where(w=>candidates.Contains(w.Path,StringComparer.OrdinalIgnoreCase)||WindowActivationRules.HostedMatch(entry,w.Path,w.AppId)).ToList();if(exact.Count>0)return exact;
var names=candidates.Select(Path.GetFileName).Where(n=>!string.IsNullOrEmpty(n)&&!new[]{"update.exe","launcher.exe","rundll32.exe","explorer.exe"}.Contains(n.ToLowerInvariant())).ToArray();
var named=windows.Where(w=>string.IsNullOrEmpty(w.Path)?names.Contains(w.ProcessName,StringComparer.OrdinalIgnoreCase):names.Contains(Path.GetFileName(w.Path),StringComparer.OrdinalIgnoreCase)).ToList();if(named.Count>0)return named;
string key=(entry.Name??"").Trim();if(key.Equals("DSH",StringComparison.OrdinalIgnoreCase))key="DeepSeek Harness";if(key.Contains("抖音"))key="douyin";if(key.Length<2)return new List<RunningWindow>();
return windows.Where(w=>!string.IsNullOrEmpty(w.Path)&&!string.IsNullOrEmpty(w.Title)&&w.Title.IndexOf(key,StringComparison.OrdinalIgnoreCase)>=0&&(Path.GetFileNameWithoutExtension(w.Path).IndexOf(key,StringComparison.OrdinalIgnoreCase)>=0||candidates.Any(p=>string.Equals(Path.GetDirectoryName(p),Path.GetDirectoryName(w.Path),StringComparison.OrdinalIgnoreCase)))).ToList();}
internal static bool WindowMatch(Entry entry,RunningWindow window){
if(entry==null||window==null||entry.IsFolder)return false;
if(IsFileManager(entry))return !string.IsNullOrWhiteSpace(window.FolderPath);
var paths=WindowActivationRules.Executables(entry);
if(paths.Any(p=>string.Equals(p,window.Path,StringComparison.OrdinalIgnoreCase)))return true;
if(WindowActivationRules.HostedMatch(entry,window.Path,window.AppId))return true;
var names=paths.Select(Path.GetFileName).Where(n=>!string.IsNullOrEmpty(n)&&!new[]{"update.exe","launcher.exe","rundll32.exe","explorer.exe"}.Contains(n.ToLowerInvariant())).ToArray();
if(names.Length==0)return false;
if(string.IsNullOrEmpty(window.Path))return !string.IsNullOrEmpty(window.ProcessName)&&names.Contains(window.ProcessName,StringComparer.OrdinalIgnoreCase);
return names.Contains(Path.GetFileName(window.Path),StringComparer.OrdinalIgnoreCase);
}
}
public partial class Controller {
static IEnumerable<FrameworkElement> SearchElements(DependencyObject node){foreach(object child in LogicalTreeHelper.GetChildren(node)){var d=child as DependencyObject;if(d==null)continue;var f=d as FrameworkElement;if(f!=null)yield return f;foreach(var nested in SearchElements(d))yield return nested;}}
void InstallSettingsSearch(StackPanel title,TabControl tabs){
var input=new TextBox{Margin=new Thickness(0,0,0,8),ToolTip="搜索设置，例如：透明度、快捷键、动效"};var results=new StackPanel();var scroll=new ScrollViewer{Content=results,MaxHeight=180,Visibility=Visibility.Collapsed};title.Children.Add(new TextBlock{Text="搜索设置",Foreground=Brushes.LightGray});title.Children.Add(input);title.Children.Add(scroll);
input.TextChanged+=(s,e)=>{results.Children.Clear();string query=input.Text.Trim();scroll.Visibility=query.Length==0?Visibility.Collapsed:Visibility.Visible;if(query.Length==0)return;int count=0;foreach(TabItem tab in tabs.Items){var root=tab.Content as DependencyObject;if(root==null)continue;foreach(var target in SearchElements(root)){string label=target is TextBlock?((TextBlock)target).Text:target is ContentControl?((ContentControl)target).Content as string:null;if(string.IsNullOrEmpty(label)||label.IndexOf(query,StringComparison.OrdinalIgnoreCase)<0)continue;var selected=target;var page=tab;var button=new Button{Content=tab.Header+" · "+label,HorizontalContentAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,2,0,2)};button.Click+=(ss,ee)=>{tabs.SelectedItem=page;input.Clear();selected.Dispatcher.BeginInvoke(new Action(()=>{selected.BringIntoView();selected.Focus();}));};results.Children.Add(button);if(++count>=40)break;}if(count>=40)break;}if(count==0)results.Children.Add(new TextBlock{Text="没有找到匹配的设置",Foreground=Brushes.LightGray});};
}}
public partial class DockWindow { bool ApplicationDropAt(DragEventArgs e){if(e.Data.GetDataPresent("GlassBoard.Entry")||e.Data.GetDataPresent("GlassBoard.Entries"))return false;foreach(var button in Items.Children.OfType<Button>()){var entry=button.Tag as Entry;if(entry==null||entry.IsFolder)continue;Point p=e.GetPosition(button);if(p.X>=0&&p.Y>=0&&p.X<=button.ActualWidth&&p.Y<=button.ActualHeight)return true;}return false;}
static string QuoteDropArgument(string value){return "\""+System.Text.RegularExpressions.Regex.Replace(value,@"(\\*)""","$1$1\\\"").TrimEnd('\\')+new string('\\',value.Reverse().TakeWhile(c=>c=='\\').Count()*2)+"\"";}
void BindApplicationDrop(FrameworkElement element,Entry entry){if(entry.IsFolder)return;element.AllowDrop=true;
Func<IDataObject,string[]> read=data=>{if(data.GetDataPresent("GlassBoard.SourceGroup")||data.GetDataPresent("GlassBoard.Entry")||data.GetDataPresent("GlassBoard.Entries"))return new string[0];if(data.GetDataPresent(DataFormats.FileDrop))return (string[])data.GetData(DataFormats.FileDrop);string text=data.GetData(DataFormats.UnicodeText) as string;Uri uri;if(Uri.TryCreate(text,UriKind.Absolute,out uri)&&(uri.Scheme=="http"||uri.Scheme=="https"))return new[]{uri.AbsoluteUri};return new string[0];};
element.DragOver+=(s,e)=>{var files=read(e.Data);if(files.Length==0)return;e.Effects=(e.AllowedEffects&DragDropEffects.Copy)!=0?DragDropEffects.Copy:DragDropEffects.None;e.Handled=true;};
element.Drop+=(s,e)=>{var files=read(e.Data);if(files.Length==0)return;e.Handled=true;try{LaunchInfoService.Enrich(entry);string target=entry.LaunchTarget;if(string.IsNullOrWhiteSpace(target)||!target.EndsWith(".exe",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("此入口不支持通过参数打开文件，请使用应用程序快捷方式。");Process.Start(new ProcessStartInfo(target){UseShellExecute=true,Arguments=(entry.LaunchArguments??"")+" "+string.Join(" ",files.Select(QuoteDropArgument))});}catch(Exception ex){MessageBox.Show("无法用该应用打开拖入的内容："+ex.Message,"GlassBoard");}};
}}
public sealed partial class ThumbnailPopup { Window snapHint; void HideSnapHint(){if(snapHint!=null){snapHint.Close();snapHint=null;}} void UpdateSnapHint(int x,int y){var screen=System.Windows.Forms.Screen.FromPoint(new System.Drawing.Point(x,y));var a=screen.WorkingArea;bool top=y<=screen.Bounds.Top+32,left=x<=screen.Bounds.Left+32,right=x>=screen.Bounds.Right-32;if(!top&&!left&&!right){HideSnapHint();return;}if(snapHint==null){snapHint=new Window{Title="GlassBoard 分屏预览",WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,ShowActivated=false,ShowInTaskbar=false,Topmost=true,IsHitTestVisible=false,Content=new Border{Background=new SolidColorBrush(Color.FromArgb(45,100,175,255)),BorderBrush=Brushes.LightSkyBlue,BorderThickness=new Thickness(2),CornerRadius=new CornerRadius(14)}};snapHint.SourceInitialized+=(ss,ee)=>{var h=new System.Windows.Interop.WindowInteropHelper(snapHint).Handle;SnapStyles.MakePassive(h);};}snapHint.Left=(top||left?a.Left:a.Left+a.Width/2)/scale;snapHint.Top=a.Top/scale;snapHint.Width=(top?a.Width:a.Width/2)/scale;snapHint.Height=a.Height/scale;snapHint.Show();}
internal static bool SnapTarget(RunningWindow window,int x,int y){if(!RunningWindows.Valid(window))return false;var screen=System.Windows.Forms.Screen.FromPoint(new System.Drawing.Point(x,y));var a=screen.WorkingArea;if(y<=screen.Bounds.Top+32){ShowWindow(window.Handle,3);return true;}bool left=x<=screen.Bounds.Left+32,right=x>=screen.Bounds.Right-32;if(!left&&!right)return false;ShowWindow(window.Handle,9);int half=a.Width/2;return SetWindowPos(window.Handle,IntPtr.Zero,left?a.Left:a.Left+half,a.Top,left?half:a.Width-half,a.Height,0x0010);} void InstallCardActions(Card card,RunningWindow window,Grid content){
var close=new Button{Content="×",Width=23,Height=22,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Top,ToolTip="关闭窗口",Background=Brushes.Transparent,Foreground=Brushes.White,BorderThickness=new Thickness(0)};content.Children.Add(close);close.Click+=(s,e)=>{e.Handled=true;if(RunningWindows.RequestClose(window)){var dismiss=DismissRequested;if(dismiss!=null)dismiss();}};
card.Root.PreviewMouseLeftButtonDown+=(s,e)=>{if(e.OriginalSource is System.Windows.Controls.Primitives.ButtonBase||close.IsMouseOver)return;POINT p;GetCursorPos(out p);card.Press=new Point(p.X,p.Y);card.PressX=card.X;card.PressY=card.Y;card.Dragged=false;card.Root.CaptureMouse();};
card.Root.MouseMove+=(s,e)=>{if(!card.Root.IsMouseCaptured||e.LeftButton!=MouseButtonState.Pressed)return;POINT p;GetCursorPos(out p);if(Math.Abs(p.X-card.Press.X)>8||Math.Abs(p.Y-card.Press.Y)>8)card.Dragged=true;if(card.Dragged){animating=false;card.X=card.PressX+(p.X-card.Press.X)/scale;card.Y=card.PressY+(p.Y-card.Press.Y)/scale;Apply(card);UpdateSnapHint(p.X,p.Y);}};
card.Root.PreviewMouseLeftButtonUp+=(s,e)=>{if(!card.Root.IsMouseCaptured)return;card.Root.ReleaseMouseCapture();HideSnapHint();if(!card.Dragged){if(animating)HookFrames();return;}e.Handled=true;POINT p;GetCursorPos(out p);var screen=System.Windows.Forms.Screen.FromPoint(new System.Drawing.Point(p.X,p.Y));var area=screen.WorkingArea;bool left=p.X<=screen.Bounds.Left+32,right=p.X>=screen.Bounds.Right-32,top=p.Y<=screen.Bounds.Top+32;if(!RunningWindows.Valid(window))return;SnapTarget(window,p.X,p.Y);if(top||left||right){var handler=Clicked;if(handler!=null)handler(card.Target);}else SetHover(-1);};card.Root.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Escape){card.Root.ReleaseMouseCapture();HideSnapHint();SetHover(-1);e.Handled=true;}};
}
